<?php
require_once __DIR__.'/includes/config.php'; require_admin();
$msg='';$error='';
try {
 if($_SERVER['REQUEST_METHOD']==='POST'){
  verify_csrf();$action=$_POST['action']??'entry';
  if($action==='entry'){$type=$_POST['entry_type']??'';$category=trim($_POST['category']??'');$desc=trim($_POST['description']??'');$amount=$_POST['amount_mwk']??'';$date=$_POST['entry_date']??date('Y-m-d');$ref=trim($_POST['reference_no']??'');if(!in_array($type,['income','expense'],true)||!$category||!$desc||!is_numeric($amount)||(float)$amount<=0||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date))throw new RuntimeException('Enter a valid income/expense entry and positive MWK amount.');$q=$dbh->prepare('INSERT INTO srms_finance_entries(entry_type,category,description,amount_mwk,entry_date,reference_no,entered_by) VALUES(?,?,?,?,?,?,?)');$q->execute([$type,$category,$desc,number_format((float)$amount,2,'.',''),$date,$ref?:null,$_SESSION['admin_id']??null]);audit_log($dbh,'FINANCE_ENTRY_CREATE',strtoupper($type).' MWK '.number_format((float)$amount,2));$msg='Financial entry recorded.';}
  elseif($action==='budget'){$year=trim($_POST['fiscal_year']??'');$cat=trim($_POST['budget_category']??'');$amount=$_POST['budget_amount_mwk']??'';if(!preg_match('/^\d{4}(-\d{4})?$/',$year)||!$cat||!is_numeric($amount)||(float)$amount<0)throw new RuntimeException('Enter a valid fiscal year, category, and non-negative budget.');$q=$dbh->prepare('INSERT INTO srms_budgets(fiscal_year,category,budget_amount_mwk,notes,created_by) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE budget_amount_mwk=VALUES(budget_amount_mwk),notes=VALUES(notes)');$q->execute([$year,$cat,number_format((float)$amount,2,'.',''),trim($_POST['budget_notes']??'')?:null,$_SESSION['admin_id']??null]);audit_log($dbh,'FINANCE_BUDGET_UPSERT','Budget '.$year.' '.$cat);$msg='Budget saved.';}
 }
 $from=$_GET['from']??date('Y-01-01');$to=$_GET['to']??date('Y-12-31');if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$from))$from=date('Y-01-01');if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$to))$to=date('Y-m-d');
 $q=$dbh->prepare("SELECT COALESCE(SUM(CASE WHEN entry_type='income' THEN amount_mwk ELSE 0 END),0) income,COALESCE(SUM(CASE WHEN entry_type='expense' THEN amount_mwk ELSE 0 END),0) expense FROM srms_finance_entries WHERE entry_date BETWEEN ? AND ?");$q->execute([$from,$to]);$totals=$q->fetch();$q=$dbh->prepare('SELECT entry_type,category,SUM(amount_mwk) total FROM srms_finance_entries WHERE entry_date BETWEEN ? AND ? GROUP BY entry_type,category ORDER BY entry_type,category');$q->execute([$from,$to]);$statement=$q->fetchAll();$q=$dbh->prepare('SELECT * FROM srms_finance_entries WHERE entry_date BETWEEN ? AND ? ORDER BY entry_date DESC,id DESC LIMIT 300');$q->execute([$from,$to]);$entries=$q->fetchAll();$budgets=$dbh->query('SELECT * FROM srms_budgets ORDER BY fiscal_year DESC,category')->fetchAll();
} catch(Throwable $e){$error=$e instanceof RuntimeException?$e->getMessage():'Finance subsystem unavailable. Apply Phase 12 migration first.';if(!($e instanceof RuntimeException))error_log('Finance accounting: '.$e->getMessage());$totals=$totals??['income'=>0,'expense'=>0];$entries=$entries??[];$statement=$statement??[];$budgets=$budgets??[];$from=$from??date('Y-01-01');$to=$to??date('Y-m-d');}
function mwk($v){return 'MWK '.number_format((float)$v,2);}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Finance & Accounting | SRMS</title><link rel="stylesheet" href="css/bootstrap.min.css"><link rel="stylesheet" href="css/main.css"><link rel="stylesheet" href="css/srms-modernization.css"><link rel="stylesheet" href="css/srms-responsive.css"><style>.money-card{border:1px solid #ddd;border-radius:8px;padding:18px;margin-bottom:12px}.money-card strong{font-size:22px}</style></head><body class="top-navbar-fixed"><div class="main-wrapper"><?php include 'includes/topbar.php';?><div class="content-wrapper"><div class="content-container"><?php include 'includes/leftbar.php';?><main class="main-page"><div class="container-fluid" style="padding:20px"><div style="display:flex;justify-content:space-between;flex-wrap:wrap"><h2>Finance & Accounting <small>Malawi Kwacha (MWK)</small></h2><a class="btn btn-default" href="dashboard.php">Dashboard</a></div><?php if($msg):?><div class="alert alert-success"><?=e($msg)?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><form class="form-inline" method="get"><label>From </label> <input type="date" name="from" value="<?=e($from)?>" class="form-control"> <label>To </label> <input type="date" name="to" value="<?=e($to)?>" class="form-control"> <button class="btn btn-default">Filter</button></form><div class="row" style="margin-top:15px"><div class="col-sm-4"><div class="money-card">Income<strong class="text-success" style="display:block"><?=mwk($totals['income'])?></strong></div></div><div class="col-sm-4"><div class="money-card">Expenditure<strong class="text-danger" style="display:block"><?=mwk($totals['expense'])?></strong></div></div><div class="col-sm-4"><div class="money-card">Net movement<strong style="display:block"><?=mwk($totals['income']-$totals['expense'])?></strong></div></div></div><div class="row"><div class="col-md-6"><div class="panel"><div class="panel-heading"><h3>Record income or expenditure</h3></div><div class="panel-body"><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="entry"><div class="form-group"><label>Entry type</label><select class="form-control" name="entry_type"><option value="income">Income</option><option value="expense">Expenditure</option></select></div><div class="form-group"><label>Category</label><input class="form-control" name="category" maxlength="100" required placeholder="Tuition, salaries, utilities"></div><div class="form-group"><label>Description</label><input class="form-control" name="description" maxlength="255" required></div><div class="form-group"><label>Amount (MWK)</label><input class="form-control" name="amount_mwk" type="number" min="0.01" step="0.01" required></div><div class="form-group"><label>Date</label><input class="form-control" name="entry_date" type="date" value="<?=date('Y-m-d')?>" required></div><div class="form-group"><label>Reference (optional)</label><input class="form-control" name="reference_no" maxlength="100"></div><button class="btn btn-primary">Save entry</button></form></div></div></div><div class="col-md-6"><div class="panel"><div class="panel-heading"><h3>Set annual budget</h3></div><div class="panel-body"><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="budget"><div class="form-group"><label>Fiscal year</label><input class="form-control" name="fiscal_year" value="<?=date('Y')?>" required placeholder="2026 or 2026-2027"></div><div class="form-group"><label>Category</label><input class="form-control" name="budget_category" required maxlength="100"></div><div class="form-group"><label>Budget (MWK)</label><input class="form-control" type="number" name="budget_amount_mwk" min="0" step="0.01" required></div><div class="form-group"><label>Notes</label><input class="form-control" name="budget_notes" maxlength="255"></div><button class="btn btn-success">Save budget</button></form></div></div></div></div><div class="panel"><div class="panel-heading"><h3>Income and expenditure statement by category</h3><p>Period: <?=e($from)?> to <?=e($to)?> · Currency: MWK</p></div><div class="panel-body table-responsive"><table class="table"><thead><tr><th>Type</th><th>Category</th><th>Total (MWK)</th></tr></thead><tbody><?php foreach($statement as $line):?><tr><td><?=e(ucfirst($line['entry_type']))?></td><td><?=e($line['category'])?></td><td><?=mwk($line['total'])?></td></tr><?php endforeach;?><?php if(!$statement):?><tr><td colspan="3">No statement entries for this period.</td></tr><?php endif;?></tbody></table></div></div><div class="panel"><div class="panel-heading"><h3>Income and expenditure ledger</h3><button class="btn btn-default" onclick="window.print()">Print / Save PDF</button></div><div class="panel-body table-responsive"><table class="table table-striped"><thead><tr><th>Date</th><th>Type</th><th>Category</th><th>Description</th><th>Reference</th><th>Amount (MWK)</th></tr></thead><tbody><?php foreach($entries as $v):?><tr><td><?=e($v['entry_date'])?></td><td><?=e(ucfirst($v['entry_type']))?></td><td><?=e($v['category'])?></td><td><?=e($v['description'])?></td><td><?=e($v['reference_no']??'')?></td><td><?=mwk($v['amount_mwk'])?></td></tr><?php endforeach;?><?php if(!$entries):?><tr><td colspan="6">No entries for this period.</td></tr><?php endif;?></tbody></table></div></div><div class="panel"><div class="panel-heading"><h3>Budgets</h3></div><div class="panel-body table-responsive"><table class="table"><thead><tr><th>Fiscal year</th><th>Category</th><th>Budget (MWK)</th><th>Notes</th></tr></thead><tbody><?php foreach($budgets as $b):?><tr><td><?=e($b['fiscal_year'])?></td><td><?=e($b['category'])?></td><td><?=mwk($b['budget_amount_mwk'])?></td><td><?=e($b['notes']??'')?></td></tr><?php endforeach;?></tbody></table></div></div><p class="text-muted">This is a basic income/expenditure register, not yet a full double-entry general ledger. Use the existing fee subsystem for student fee receipts; do not manually duplicate fee payments here.</p></div></body></html>
